mapper.select:
		select distinct
			PROD_ID id,
			PROD_ABBR text
			/* 多级法人改造    需查询出fin_product.finprod_id字段   add by caojin  2020/6/9    start*/
			,fin_product.finprod_id finprodId
			/* 多级法人改造    需查询出fin_product.finprod_id字段   add by caojin  2020/6/9    end*/
		from
			REP_PROD_INFO
		/* 多级法人改造    需查询出fin_product.finprod_id字段   add by caojin  2020/6/9    start*/
		LEFT JOIN fin_product
		ON fin_product.FINPROD_MARKET_ID = REP_PROD_INFO.PROD_ID
		and fin_product.P_FINPROD_ID is null
		/* 多级法人改造    需查询出fin_product.finprod_id字段   add by caojin  2020/6/9    end*/
	    where STATUS='E'
	    /* and p_prod_id is null 不取子产品*/

	    	and (PROD_ID like '%' || #{search, jdbcType=VARCHAR} || '%'
            or PROD_ABBR like '%' || #{search, jdbcType=VARCHAR} || '%')


			 ${condition}

select distinct INDENTIFY_MARK id, HOLDER_NAME text from CHB_EQU_HOLD where STATUS='E'
and (INDENTIFY_MARK like '%' || #{search, jdbcType=VARCHAR} || '%' or HOLDER_NAME like '%' || #{search, jdbcType=VARCHAR} || '%')
${condition}

select distinct PROD_ID id, PROD_ABBR text from REP_PROD_INFO where STATUS='E' and rep_prod_type in ('02','03')
and (PROD_ID like '%' || #{search, jdbcType=VARCHAR} || '%' or PROD_ABBR like '%' || #{search, jdbcType=VARCHAR} || '%')
and P_PROD_ID=#{pprodid}
${condition}

select distinct DPF.PROD_DISCOUNT_ID id, DPF.FEENAME text from DIS_PROD_FEEDISCOUNT DPF left join REP_PROD_INFO RPI on DPF.prod_id=RPI.prod_id where STATUS='E'
and (DPF.PROD_DISCOUNT_ID like '%' || #{search, jdbcType=VARCHAR} || '%' or DPF.FEENAME like '%' || #{search, jdbcType=VARCHAR} || '%')
and RPI.P_PROD_ID=#{pprodid}

select distinct DPA.PROD_ID id, DPA.ADJ_FIELD text from DIS_PROD_ADJUST DPA left join REP_PROD_INFO RPI on DPA.prod_id=RPI.prod_id where DPA.DATA_STATUS='01'
and (DPA.PROD_ID like '%' || #{search, jdbcType=VARCHAR} || '%' or DPA.ADJ_FIELD like '%' || #{search, jdbcType=VARCHAR} || '%')
and RPI.P_PROD_ID=#{pprodid}
